        "notes": "Charges shifted to satisfy total charge constraint"
      },
      {
        "ingredient": "Force computation via autograd",
        "implemented": true,
        "notes": "Forces computed as negative gradient of total energy w.r.t. positions"
      },
      {
        "ingredient": "Training on energy AND forces (no charge labels)",
        "implemented": true,
        "notes": "Joint energy+force loss; no explicit charge supervision"
      },
      {
        "ingredient": "Charge state embedding for multi-charge-state systems",
        "implemented": true,
